insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-b1-14','en-b1-14',null,3,14,'published',1,'{"id":"en-b1-14","baseId":"en-b1-14","revision":1,"level":"B1","levelIndex":3,"order":14,"title":"Question tags va tasdiqlash ohangi","objective":"Qisqa tag bilan ma’lumotni tekshirasiz va suhbatni davom ettirasiz.","context":"Sinf tadbirining vaqtini va vazifalarini qayta tasdiqlaydi.","prerequisites":["en-b1-13"],"minutes":40,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you?","Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she?","Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl."],"pattern":"You’re ready, aren’t you? / She likes it, doesn’t she?","examples":["You are ready, aren’t you?","The meeting starts at four, doesn’t it?","Ali didn’t call, did he?","We can use this room, can’t we?","I am in the right place, aren’t I?","You have finished, haven’t you?"],"vocabulary":[{"id":"en-b1-14-v0","term":"confirm","meaning":"tasdiqlamoq","ipa":"/kənˈfɜːm/","collocation":"confirm a detail","example":"“The meeting starts at four, doesn’t it?” Ali looks at the notice and confirms the time."},{"id":"en-b1-14-v1","term":"expect","meaning":"kutmoq","ipa":"/ɪkˈspekt/","collocation":"expect agreement","example":"Lola had expected agreement, but the tag helped reveal a wrong detail."},{"id":"en-b1-14-v2","term":"tone","meaning":"ohang","ipa":"/təʊn/","collocation":"a rising tone","example":"a rising tone"},{"id":"en-b1-14-v3","term":"detail","meaning":"tafsilot","ipa":"/ˈdiːteɪl/","collocation":"check a detail","example":"Lola had expected agreement, but the tag helped reveal a wrong detail."}],"visuals":[{"kind":"dialogue","title":"Ma’no va tuzilish","items":["You’re ready, aren’t you? / She likes it, doesn’t she?","You are ready, aren’t you?","The meeting starts at four, doesn’t it?"]},{"kind":"story","title":"Vaziyatni gapga aylantiring","items":["Sinf tadbirining vaqtini va vazifalarini qayta tasdiqlaydi.","Ali didn’t call, did he?","I am in the right place, aren’t I?"]}],"pronunciation":{"focus":"Bir tagni chin savol ohangi va kutilayotgan tasdiq ohangi bilan ikki marta ayting.","text":"We can use this room, can’t we?","audio":"/english-course/v7.23/en-b1-14-dictation.mp3"},"exercises":[{"id":"en-b1-14-choice","type":"choice","skill":"grammar","prompt":"Inkor gap tagini tanlang: He didn’t call, …","answers":["did he?"],"explanation":"Inkor gap → tasdiq did he.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["did he?","didn’t he?","does he?"]},{"id":"en-b1-14-gap","type":"grammarFill","skill":"grammar","prompt":"She likes it, ___ she?","answers":["doesn’t"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?"},{"id":"en-b1-14-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["You are ready, aren’t you?"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","tokens":["You","are","ready,","aren’t","you?"]},{"id":"en-b1-14-fix","type":"correction","skill":"grammar","prompt":"You are ready, don’t you?","answers":["You are ready, aren’t you?"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?"},{"id":"en-b1-14-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["tasdiqlamoq","kutmoq","ohang","tafsilot"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","left":["confirm","expect","tone","detail"],"options":["tasdiqlamoq","kutmoq","ohang","tafsilot"]}],"reading":{"title":"Question tags va tasdiqlash ohangi — vaziyat","text":"Before the club presentation, Lola checks the arrangements. “The meeting starts at four, doesn’t it?” Ali looks at the notice and confirms the time. “We can use the library, can’t we?” she asks next. The teacher explains that the library is busy, so the meeting is in Room 5. Lola had expected agreement, but the tag helped reveal a wrong detail. Ali asks whether everyone has finished their slides. “You haven’t added the last photo, have you?” he asks one classmate. The classmate says the photo is ready but needs a caption. Their questions are not complaints. They are a way to check facts before the event. The teacher reminds them that a tag does not make a false statement true; the listener must still have room to disagree.","sentences":["Before the club presentation, Lola checks the arrangements.","“The meeting starts at four, doesn’t it?","” Ali looks at the notice and confirms the time.","“We can use the library, can’t we?","” she asks next.","The teacher explains that the library is busy, so the meeting is in Room 5.","Lola had expected agreement, but the tag helped reveal a wrong detail.","Ali asks whether everyone has finished their slides.","“You haven’t added the last photo, have you?","” he asks one classmate.","The classmate says the photo is ready but needs a caption.","Their questions are not complaints.","They are a way to check facts before the event.","The teacher reminds them that a tag does not make a false statement true; the listener must still have room to disagree."],"questions":[{"id":"en-b1-14-reading0","type":"choice","skill":"reading","prompt":"Tag qaysi noto‘g‘ri detalni aniqladi?","answers":["the room"],"explanation":"Library band, Room 5 ishlatiladi.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["the room","the presentation language","the date of birth"]},{"id":"en-b1-14-reading1","type":"choice","skill":"reading","prompt":"Tag nimani kafolatlamaydi?","answers":["that the statement is true"],"explanation":"Tinglovchi e’tiroz qila olishi kerak.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["that the statement is true","a chance to check","a short question"]},{"id":"en-b1-14-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["Before the club presentation, Lola checks the arrangements.","“The meeting starts at four, doesn’t it?","” Ali looks at the notice and confirms the time.","“We can use the library, can’t we?","” she asks next.","The teacher explains that the library is busy, so the meeting is in Room 5.","Lola had expected agreement, but the tag helped reveal a wrong detail.","Ali asks whether everyone has finished their slides.","“You haven’t added the last photo, have you?","” he asks one classmate.","The classmate says the photo is ready but needs a caption.","Their questions are not complaints.","They are a way to check facts before the event.","The teacher reminds them that a tag does not make a false statement true; the listener must still have room to disagree."]}]},"listening":{"title":"Suhbatni tushunish","transcript":"The meeting starts at four, doesn’t it? Yes. We can use the library, can’t we? No, it is busy. We are meeting in Room 5. You have finished your slides, haven’t you?","audio":"/english-course/v7.23/en-b1-14.mp3","synthetic":true,"questions":[{"id":"en-b1-14-listening0","type":"choice","skill":"listening","prompt":"Uchrashuv xonasi?","answers":["Room 5"],"explanation":"Kutubxona band deb tuzatiladi.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["Room 5","the library","Room 4"]},{"id":"en-b1-14-listening1","type":"choice","skill":"listening","prompt":"Uchrashuv vaqti?","answers":["four"],"explanation":"Starts at four.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["four","five","six"]},{"id":"en-b1-14-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["four","5"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","rows":["Vaqt","Xona"]},{"id":"en-b1-14-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["We can use this room, can’t we?"],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","audio":"/english-course/v7.23/en-b1-14-dictation.mp3","transcript":"We can use this room, can’t we?"}]},"writing":{"task":"Tadbir tayyorgarligini tekshirish uchun uchta tag savoli va olingan javoblarni yozing.","audience":"Sinfdagi sherigingiz","minWords":90,"maxWords":220,"plan":["Vaziyatni ayting.","Darsdagi til vositasidan foydalaning.","Muhim tafsilot yoki sabab qo‘shing.","O‘qib, ma’no va shaklni tekshiring."],"model":"I checked our presentation plan with Ali. The meeting starts at four, doesn’t it? He confirmed the time. We can use the library, can’t we? That detail was wrong because another group had booked it. We are using Room 5 instead. You have finished the slides, haven’t you? Ali said he still needed one caption. We agreed to check it together before lunch. The questions helped us find problems without blaming anyone. I then wrote a clear message for the class so that everyone had the same room, time and task information.","modelNotes":["Birinchi gap maqsadni belgilaydi.","Darsdagi tuzilma vaziyatga xizmat qiladi.","Oxirgi gap fikrni yakunlaydi."],"phrases":["You are ready, aren’t you?","The meeting starts at four, doesn’t it?","Ali didn’t call, did he?"],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Tagni ko‘tariluvchi va pasayuvchi ohang bilan ayting va javobdagi farqni muhokama qiling.","seconds":75,"prompts":["Asosiy fikringiz nima?","Bitta tafsilot yoki misol qo‘shing.","Sherigingizning savoliga javob bering."],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Tadbir tayyorgarligini tekshirish uchun uchta tag savoli va olingan javoblarni yozing.","exit":[[{"id":"en-b1-14-exit0","type":"grammarFill","skill":"grammar","prompt":"We can use it, ___ we?","answers":["can’t"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?"},{"id":"en-b1-14-exit1","type":"grammarFill","skill":"grammar","prompt":"You have finished, ___ you?","answers":["haven’t"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?"},{"id":"en-b1-14-exit2","type":"grammarFill","skill":"grammar","prompt":"I am right, ___ I?","answers":["aren’t"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?"},{"id":"en-b1-14-exit3","type":"choice","skill":"grammar","prompt":"Tagda qaysi ega shakli odatiy?","answers":["pronoun"],"explanation":"It/he/she/we kabi olmosh.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["pronoun","full list of nouns","no subject"]},{"id":"en-b1-14-exit4","type":"choice","skill":"grammar","prompt":"Tag yolg‘on fikrni to‘g‘ri qiladimi?","answers":["No"],"explanation":"Savol tasdiqni tekshiradi.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["No","Yes","Always"]}],[{"id":"en-b1-14-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["The meeting starts at four, doesn’t it?"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","tokens":["The","meeting","starts","at","four,","doesn’t","it?"]},{"id":"en-b1-14-exit-b1","type":"grammarFill","skill":"grammar","prompt":"You have finished, ___ you?","answers":["haven’t"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?"},{"id":"en-b1-14-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["We can use this room, can’t we?"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","tokens":["We","can","use","this","room,","can’t","we?"]},{"id":"en-b1-14-exit-b3","type":"choice","skill":"grammar","prompt":"Tagda qaysi ega shakli odatiy?","answers":["pronoun"],"explanation":"It/he/she/we kabi olmosh.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","options":["pronoun","full list of nouns","no subject"]},{"id":"en-b1-14-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["You have finished, haven’t you?"],"explanation":"Tasdiq gapda odatda inkor tag, inkor gapda tasdiq tag: You are ready, aren’t you? You didn’t call, did you? Tagda yordamchi fe’l va ega olmoshi saqlanadi. Present Simple harakatida do/does: She likes it, doesn’t she? Ohang ma’noga ta’sir qiladi: ko‘tarilish ko‘proq tekshirish, pasayish ko‘proq kutayotgan tasdiq. I am …, aren’t I? maxsus odatiy shakl.","hint":"You’re ready, aren’t you? / She likes it, doesn’t she?","tokens":["You","have","finished,","haven’t","you?"]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-b1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-b1-14","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-b1-14","verified":"2026-10-05","mode":"l